/* permission gate */
.pg-head{display:flex;gap:14px;align-items:flex-start;padding:18px 16px 14px}
.pg-q{font-weight:600;font-size:16px;line-height:1.4}
.pg-d{margin-top:4px;font-size:13px;color:var(--text-dim)}
.pg-scopes{border-top:1px solid var(--line);padding:6px 0}
.pg-scope{display:flex;align-items:center;gap:12px;width:100%;padding:9px 16px;font-size:13px;text-align:left;color:var(--text-dim);transition:color .25s}
.pg-scope.on{color:var(--text)}
.pg-scope .pill{margin-left:auto}
.pg-dur{padding:12px 16px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:12px}
.pg-foot{display:flex;justify-content:flex-end;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.pg-foot .btn{padding:8px 14px;font-size:13px}
.pg-granted{padding:20px 16px;display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.pg-granted .tags{display:flex;flex-wrap:wrap;gap:6px}
.seg{position:relative;display:flex;border:1px solid var(--line)}
.seg button{position:relative;z-index:1;padding:6px 10px;font-size:12px;font-weight:600;color:var(--muted);transition:color .3s;white-space:nowrap}
.seg button.on{color:var(--accent)}
.seg-ind{position:absolute;top:0;bottom:0;left:0;width:0;background:var(--accent-bg);box-shadow:inset 0 -1px 0 var(--accent);transition:transform .45s var(--ease),width .45s var(--ease)}

/* ---------- permission gate, stepped ---------- */
#pg{max-width:360px}
.pg-hero{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:18px 16px 14px}
.pg-hero .nbox{width:36px;height:36px;margin-bottom:8px;box-shadow:none;border-color:var(--accent-icon-line);background:var(--accent-icon-bg);color:var(--accent)}
.pg-q{font-weight:600;font-size:15px;line-height:1.35}
.pg-q.sm{font-size:14px}
.pg-d{margin-top:0;font-size:13px;line-height:1.45;color:var(--text-dim)}
.pg-sub{padding:14px 16px 4px}
.pg-scopes{border-top:0;padding:2px 0 8px}
.pg-st{display:flex;flex-direction:column;align-items:flex-start;gap:1px}
.pg-sd{font-size:12px;color:var(--muted)}
.pg-durs{display:flex;flex-direction:column;padding:2px 0 8px}
.pg-dur{display:flex;align-items:center;gap:12px;width:100%;padding:9px 16px;border:0;border-top:0;font-size:13px;text-align:left;color:var(--text-dim);transition:color .2s}
.pg-dur.on{color:var(--text)}
.pg-dur .pg-sd{margin-left:auto}
.pg-rd{width:14px;height:14px;flex:none;border-radius:50%;border:1px solid var(--icon-line);transition:border .2s}
.pg-dur.on .pg-rd{border:4px solid var(--accent)}
.pg-foot{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:12px 16px;border-top:1px solid var(--line)}
.pg-steps{display:flex;gap:4px}
.pg-steps i{width:14px;height:3px;border-radius:2px;background:var(--line);transition:background-color .3s}
.pg-steps i.on{background:var(--accent)}
.pg-btns{display:flex;gap:8px}
.pg-done{display:flex;flex-direction:column;align-items:flex-start;gap:4px;padding:18px 16px 16px}
.pg-done .nbox{box-shadow:none;margin-bottom:8px}
.pg-done .btn{margin-top:10px}

/* ---------- permission gate ---------- */
{
  const pg = $('#pg');
  const scopes = [['Read threads','See emails in your inbox',''],['Create drafts','Write replies for you to send',''],['Send messages','Send email without asking','Higher risk']];
  const durs = [['Once','Only this email'],['This project','Until it closes'],['Always','Until you revoke it']];
  let state = [false, false, false], dur = 'This project', step = 0;
  const dots = () => `<div class="pg-steps">${[0,1,2].map(i => `<i class="${i <= step ? 'on' : ''}"></i>`).join('')}</div>`;
  function view(){
    if (step === 0) return `<div class="pg-hero"><div class="pg-q">Let the agent use your inbox?</div><div class="pg-d">It needs access to draft the follow-up after your kickoff call.</div></div>
      <div class="pg-foot">${dots()}<div class="pg-btns"><button class="btn" data-a="deny">Not now</button><button class="btn primary" data-a="next">Continue</button></div></div>`;
    if (step === 1) return `<div class="pg-sub"><div class="pg-q sm">What can it do?</div></div><div class="pg-scopes">${scopes.map((s, i) => `<button class="pg-scope ${state[i] ? 'on' : ''}" data-i="${i}"><span class="cb ${state[i] ? 'on' : ''}">${ic('check')}</span><span class="pg-st"><span>${s[0]}</span><span class="pg-sd">${s[1]}</span></span>${s[2] ? `<span class="pill fail">${s[2]}</span>` : ''}</button>`).join('')}</div>
      <div class="pg-foot">${dots()}<div class="pg-btns"><button class="btn" data-a="back">Back</button><button class="btn primary" data-a="next" ${state.some(Boolean) ? '' : 'disabled'}>Next</button></div></div>`;
    return `<div class="pg-sub"><div class="pg-q sm">For how long?</div></div><div class="pg-durs">${durs.map(d => `<button class="pg-dur ${d[0] === dur ? 'on' : ''}" data-d="${d[0]}"><span class="pg-rd"></span><span>${d[0]}</span><span class="pg-sd">${d[1]}</span></button>`).join('')}</div>
      <div class="pg-foot">${dots()}<div class="pg-btns"><button class="btn" data-a="back">Back</button><button class="btn primary" data-a="allow">Allow access</button></div></div>`;
  }
  const render = () => morph(pg, () => { pg.innerHTML = `<div class="enter">${view()}</div>`; });
  pg.addEventListener('click', e => {
    const sc = e.target.closest('.pg-scope'), du = e.target.closest('.pg-dur'), a = e.target.closest('[data-a]');
    if (sc){ const i = +sc.dataset.i; state[i] = !state[i]; sc.classList.toggle('on', state[i]); sc.querySelector('.cb').classList.toggle('on', state[i]); const n = $('[data-a="next"]', pg); if (n) n.disabled = !state.some(Boolean); Sound.play('tick'); return; }
    if (du){ dur = du.dataset.d; $$('.pg-dur', pg).forEach(x => x.classList.toggle('on', x === du)); Sound.play('tick'); return; }
    if (!a) return;
    const act = a.dataset.a;
    if (act === 'next'){ step++; Sound.play('tab'); render(); }
    else if (act === 'back'){ step--; Sound.play('tab'); render(); }
    else if (act === 'deny'){ Sound.play('close'); morph(pg, () => { pg.innerHTML = `<div class="pg-done enter"><div class="pg-q sm">Access not granted</div><div class="pg-d">You can send the follow-up yourself.</div><button class="btn" data-a="reset">${ic('undo','sm')}Undo</button></div>`; }); }
    else if (act === 'allow'){ Sound.play('done'); morph(pg, () => { pg.innerHTML = `<div class="pg-done enter"><span class="nbox" style="color:var(--success)">${ic('check_circle','icon-in')}</span><div class="pg-q sm">Access granted</div><div class="pg-d">${dur}, ${scopes.filter((s, i) => state[i]).map(s => s[0].toLowerCase()).join(' and ')}</div><button class="btn" data-a="reset">Revoke</button></div>`; }); }
    else if (act === 'reset'){ step = 0; Sound.play('tab'); render(); }
  });
  pg.innerHTML = `<div>${view()}</div>`;
}
